from fastapi import FastAPI
from fastapi.sse import ServerSentEvent
import pytest
from pydantic import ValidationError

def test_sse_validation():
    # This should pass
    ServerSentEvent(event="test", id="123")

    # This should fail (newline in event)
    try:
        ServerSentEvent(event="test\nnewline", id="123")
    except ValidationError as e:
        print(f"Caught expected error for event newline: {e}")
    else:
        print("Failed to catch newline in event")

    # This should fail (newline in id)
    try:
        ServerSentEvent(event="test", id="123\nnewline")
    except ValidationError as e:
        print(f"Caught expected error for id newline: {e}")
    else:
        print("Failed to catch newline in id")

    # This should fail (null in id)
    try:
        ServerSentEvent(event="test", id="123\0null")
    except ValidationError as e:
        print(f"Caught expected error for id null: {e}")
    else:
        print("Failed to catch null in id")

    # This should pass (newline in data)
    ServerSentEvent(raw_data="test\nnewline")
    print("Newline in raw_data passed as expected")

if __name__ == "__main__":
    test_sse_validation()

